#ifndef THICKET_HTTP_H
#define THICKET_HTTP_H

#include <stdint.h>

/* --- requests ---------------------------------------------------------------- */
/* Starts a request and returns its id at once. `headers` is "Name: value" lines separated by
   \n; a name may repeat. `body` may be NULL when `bodyLength` is 0, and is copied before this
   returns. `timeoutMs` is URLSession's idle timeout, 0 for its default. Every id must be freed. */
int64_t thk_http_send(const char *method, const char *url, const char *headers, const uint8_t *body,
                      int64_t bodyLength, int32_t timeoutMs);
/* Blocks up to `waitMs` for the request to finish: 1 finished (or failed), 0 still running,
   -1 no such request. Scala marks the call blocking for the GC, so it may park for as long as it likes. */
int32_t thk_http_wait(int64_t request, int32_t waitMs);
/* Cancels the URLSession task. The request then finishes with error 4 (cancelled). */
void thk_http_cancel(int64_t request);
/* Forgets the request and everything it holds; its pointers die with it. */
void thk_http_free(int64_t request);

/* --- results ----------------------------------------------------------------- */
/* Valid once thk_http_wait has returned 1, until thk_http_free. */
/* The HTTP status code, or 0 if no response arrived. */
int32_t thk_http_status(int64_t request);
/* The response's headers as "Name: value" lines separated by \n. Foundation joins a repeated
   header into one line with ", "; Set-Cookie is split back apart here. Owned by the request. */
const char *thk_http_headers(int64_t request);
int64_t thk_http_body_length(int64_t request);
/* The response body, owned by the request. NULL when it is empty. */
const uint8_t *thk_http_body(int64_t request);
/* 0 none, 1 connect (the request was not sent), 2 read, 3 timeout, 4 cancelled, 5 the request
   could not be built (a malformed URL). */
int32_t thk_http_error(int64_t request);
/* The platform's description of the error, or "". */
const char *thk_http_error_message(int64_t request);

/* --- inspection -------------------------------------------------------------- */
/* 1 on the process's main thread. The backend refuses to block it under a self-test. */
int32_t thk_http_on_main_thread(void);
/* How many requests have not been freed, for a self-test's leak check. */
int32_t thk_http_live(void);

#endif
